[
  {
    "alert_id": "ALERT_001",
    "title": "TDF toxicity: low phosphate and bone pain",
    "message": "Guidelines list TDF as causing Fanconi syndrome, decreased bone mineral density, and lower back pain/bone aches, with management including LFTs and RFTs. Patient on TDF for 6 years presents with serum phosphate 0.78 mmol/L (low), trace proteinuria, and chronic lower back pain with thigh heaviness worsening over 4 months. Evidence for TDF attribution: hypophosphataemia and proteinuria are hallmark proximal tubulopathy findings; bone pain aligns with TDF-related bone mineral density loss. Evidence against: back pain may be occupational from truck driving; proteinuria may be secondary to uncontrolled hypertension. Ibuprofen use could also contribute to renal tubular effects.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Do serum creatinine, eGFR, and urine for phosphate/glucose to assess TDF tubulopathy. Consider TDF substitution if Fanconi syndrome confirmed. Evaluate bone density.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  },
  {
    "alert_id": "ALERT_002",
    "title": "TDF monitoring gap: no eGFR or creatinine trend",
    "message": "Guidelines require serum creatinine and eGFR monitoring for patients on TDF. Patient has a single creatinine of 112 umol/L today with no prior creatinine values available for trend assessment. Trace proteinuria is present on urinalysis. Without eGFR calculation or serial creatinine trends, early TDF nephrotoxicity cannot be excluded. The clinician's plan does not include renal monitoring or follow-up labs.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Calculate eGFR from today's creatinine. Schedule serial creatinine and urinalysis monitoring per TDF guidelines. Add renal function tests to follow-up plan.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "Ibuprofen plus TDF: compounded nephrotoxicity risk",
    "message": "Patient uses over-the-counter ibuprofen as needed for back pain while on TDF-containing ART. NSAIDs can reduce renal perfusion and, combined with TDF's proximal tubular toxicity, may compound kidney injury risk. Patient already has trace proteinuria and low serum phosphate, which may indicate early renal tubular dysfunction. Uncontrolled hypertension adds further renal stress.",
    "issue_type": "drug_interaction",
    "severity": "moderate",
    "recommended_action": "Counsel patient to limit ibuprofen use. Consider alternative analgesia. Monitor renal function and proteinuria closely given combined TDF and NSAID exposure.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  },
  {
    "alert_id": "ALERT_004",
    "title": "Plan omits EFV toxicity assessment for CNS symptoms",
    "message": "Guidelines describe EFV-related persistent CNS toxicity and management including dose reduction to 400 mg or substitution with DTG if symptoms persist. Patient on EFV-based regimen for 6 years reports thigh heaviness and stiff gait. While these symptoms are more consistent with musculoskeletal or TDF-related issues, no assessment for EFV CNS effects was documented. The plan continues EFV without review.",
    "issue_type": "plan_review",
    "severity": "low",
    "recommended_action": "Screen for EFV CNS symptoms (dizziness, insomnia, abnormal dreams, anxiety). If present, consider EFV dose reduction or substitution per guidelines.",
